# Exact short relations of K(nm) and the Schreier section subgroup G_1 = phi_0(St_K(0)).
# Emits a GAP file: A_L = < letters | all cyclically reduced trivial words of length <= L >,
# G1 = subgroup of A_L generated by the 0-sections of Schreier generators of St(0).
# Usage: python3 amalg.py nm L out.g
import sys, itertools as it
from aut import AUT
from agrp import AG
nm=sys.argv[1]; L=int(sys.argv[2]); fn=sys.argv[3]
out,sec=AUT[nm]; n=len(out)
A=AG([out[g] for g in range(n)],[sec[g] for g in range(n)])
for g in range(n): assert A.trivial((g,g))==True      # all letters are involutions (exact)
def act(w,x):
    s=list(w)
    for j in range(len(w)-1,-1,-1):
        a=s[j]; s[j]=sec[a][x]; x=out[a][x]
    return x,tuple(s)
def red(w):
    r=[]
    for g in w:
        if r and r[-1]==g: r.pop()
        else: r.append(g)
    return tuple(r)
def tr(w):  # exact triviality, letters involutions (inverse state = letter itself in AG terms: use g, since g=g^-1)
    return A.trivial(tuple(w))
# relations: cyclically reduced words (no x x, first!=last), up to rotation/reversal, length<=L
rels=[]; seen=set()
for l in range(2,L+1):
    for w in it.product(range(n),repeat=l):
        if any(w[i]==w[i+1] for i in range(l-1)) or w[0]==w[-1]: continue
        c=min(min(w[i:]+w[:i],tuple(reversed(w[i:]+w[:i]))) for i in range(l))
        if c in seen: continue
        seen.add(c)
        # skip words containing a shorter known relation as cyclic subword? keep all (harmless)
        r=tr(w)
        assert r is not None
        if r: rels.append(c)
    print('len',l,'rels so far',len(rels),flush=True)
# minimal relations: drop those that are consequences? keep all; GAP handles it.
# Schreier generators of St(0)
top=[out[g] for g in range(n)]
T={0:()}; todo=[0]
while todo:
    x=todo.pop()
    for g in range(n):
        y=top[g][x]
        if y not in T: T[y]=red((g,)+T[x]); todo.append(y)
assert len(T)==3
gens=set()
for x,t in T.items():
    for g in range(n):
        y=top[g][x]
        s=red(tuple(reversed(T[y]))+(g,)+t)     # T[y]^-1 g T[x] fixes 0
        z,u=act(s,0); assert z==0
        u=red(u)
        if u: gens.add(u)
gens=sorted(gens,key=lambda w:(len(w),w))
print('G1 gens',[''.join(map(str,g)) for g in gens])
nm_=lambda g:'x%d'%g
def gw(w): return '*'.join(nm_(g) for g in w) if w else 'One(F)'
with open(fn,'w') as f:
    f.write('F:=FreeGroup(%s);;\n'%','.join('"x%d"'%g for g in range(n)))
    for g in range(n): f.write('%s:=F.%d;;\n'%(nm_(g),g+1))
    R=['%s^2'%nm_(g) for g in range(n)]+[gw(r) for r in rels]
    f.write('R:=[%s];;\n'%',\n'.join(R))
    f.write('A:=F/R;;\nag:=GeneratorsOfGroup(A);;\n')
    f.write('G1w:=[%s];;\n'%','.join(gw(g) for g in gens))
    f.write('G1:=Subgroup(A,List(G1w,w->MappedWord(w,GeneratorsOfGroup(F),ag)));;\n')
print('rels',len(rels),[''.join(map(str,r)) for r in rels[:40]])
